fn check(b:bool){if !b{let z=0;let _=1/z;}}struct V{value:u8,c:*mut u32}impl Drop for V{fn drop(&mut self){unsafe{*self.c+=1u32;}}}struct D{cur:u8,end:u8,c:*mut u32}impl Drop for D{fn drop(&mut self){unsafe{*self.c+=100u32;}}}impl core::iter::Iterator for D{type Item=V;fn next(&mut self)->Option<V>{if self.cur<self.end{let v=self.cur;self.cur+=1u8;Some(V{value:v,c:self.c})}else{None}}}fn dropping(c:*mut u32)->D{D{cur:0,end:3,c}}fn run(p:*mut u32){for v in dropping(p){check(v.value==0);return;}}fn main(){let mut drops=0u32;run(&mut drops as *mut u32);check(drops==101);}

